class ListStack:
    def __init__(self):
        self.stack = []

    def push(self, x):
        self.stack.append(x)

    def pop(self):
        return self.stack.pop()

    def isEmpty(self):
        return len(self.stack) == 0

    def printStack(self):
        print(self.stack)

    def reverse(self):
        temp = []


        while not self.isEmpty():
            temp.append(self.pop())


        for item in temp:
            self.push(item)

